		95000:  "1.6", // 98000/6000 = 16
		60000:  "1.0",
		600000: "10.0",
	}
	for ms, want := range cases {
		if got := FormatMinutes(ms); got != want {
			t.Errorf("FormatMinutes(%d) = %q, want %q", ms, got, want)
		}
	}
